import{_ as t,o as d,a,b as r}from"./app.UgfkfLuP.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"基础定义","link":"/api/SIMD-API/c_api/defs/defs"},{"text":"寄存器类型","link":"/api/SIMD-API/c_api/defs/type/type"},{"text":"寄存器类型总览","link":"/api/SIMD-API/c_api/defs/type/reg_data_types"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/defs/type/reg_data_types.md","filePath":"api/SIMD-API/c_api/defs/type/reg_data_types.md","outlineHeaders":[{"level":2,"title":"使用说明","slug":"使用说明","link":"#使用说明"}],"lastUpdated":1790563388000}'),_={name:"api/SIMD-API/c_api/defs/type/reg_data_types.md"};function o(c,e,i,l,p,s){return d(),a("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>寄存器类型</h1><p>Ascend 950PR&amp;950DT系列产品（NPU架构版本3510）的C API提供矢量数据寄存器、掩码寄存器、非对齐搬运寄存器和地址寄存器类型。寄存器类型主要在AIV的Vector Function（<code>__simd_vf__</code>标记的函数）内使用，最细粒度公共头文件为<code>c_api/defs/type.h</code>。</p><p>各类寄存器的用途如下。</p><table><thead><tr><th>C API类型</th><th>用途</th></tr></thead><tbody><tr><td><code>vector_&lt;dtype&gt;</code>，例如<code>vector_int8_t</code>、<code>vector_half</code>、<code>vector_float</code></td><td>保存矢量计算的数据操作数和结果。NPU架构版本3510的矢量数据寄存器长度为256字节。</td></tr><tr><td><code>vector_bool</code></td><td>按元素控制矢量指令是否生效。掩码寄存器长度为256 bit。</td></tr><tr><td><code>vector_load_unalign</code></td><td>保存UB非对齐加载的中间状态。</td></tr><tr><td><code>vector_store_unalign</code></td><td>保存UB非对齐存储的中间状态。</td></tr><tr><td><code>addr_reg</code></td><td>保存地址偏移，配合支持地址寄存器的Reg接口使用。</td></tr></tbody></table><h2 id="使用说明">使用说明<a class="header-anchor" href="#使用说明">​</a></h2><ul><li>矢量数据寄存器类型根据元素位宽分为b8、b16、b32和b64类别。完整类型列表和打包类型说明请参见<a href="data_type_definition.html">寄存器类型定义</a>。</li><li><code>vector_bool</code>既可以由掩码生成接口构造，也可以通过<a href="../../reg_compute/reg_mask/asc_get_mask_spr.html">asc_get_mask_spr</a>读取特殊寄存器中的掩码值。</li><li>Reg与UB之间的数据交换通过<a href="../../reg_compute/load/reg_load_overview.html">Reg加载</a>和<a href="../../reg_compute/store/reg_store_overview.html">Reg存储</a>接口完成。GM中的数据不能直接加载到Reg，需要先搬运到UB。</li><li><code>vector_load_unalign</code>和<code>vector_store_unalign</code>只用于对应的非对齐加载、存储接口序列，不用于一般矢量计算。</li><li><code>addr_reg</code>可通过<a href="../../reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>更新。寄存器对象的有效范围由Vector Function和具体接口约束共同决定。</li></ul></article></div>',1)])])}const h=t(_,[["render",o]]);export{g as __pageData,h as default};
